include <robotics.scad>
// Stereolabs ZED Mini housing — datasheet Rev1.3 p.4 (first-angle drawing).
// World frame: base z=0, lenses face -Y, long side along X, bbox centred in X/Y.
W      = 125.2;   // body width (drawing)
H      = 26.6;    // body height (drawing)
D_tot  = 30.25;   // total depth incl. lens bosses (drawing)
D_body = 13;      // main body depth (drawing)
bez_d  = 1.44;    // front bezel depth = 14.44 - 13 (drawing)
bez_in = 1.72;    // bezel inset from body ends (drawing)
end_flat = 23.17; // end-view flat face height (drawing)
r_c    = (H - end_flat)/2;  // 1.715 front-view corner radius, derived from 26.6 - 23.17
r_bez  = 0.5;     // bezel corner radius — NOT dimensioned
boss_base = 20.53; boss_tip = 18.78;   // lens boss Ø (drawing)
lens_x = [-40.20, 22.80];              // lens centres, 63 baseline (derived from drawing)
glass_d = 14; glass_rec = 1.0;         // glass recess — NOT dimensioned
usb_h = 9.5; usb_w = 3.5; usb_depth = 7; // opening (drawing); depth NOT dimensioned
m2_d = 2; m2_depth = 2.3;              // M2x0.4, max engagement 2.3 (drawing)
rear_dx = 116.7; rear_dz = 18.1;       // rear hole pattern (drawing)
bot_dx = 56;                           // bottom hole spacing (drawing)

y_rear  = D_tot/2;
y_body  = y_rear - D_body;             // main body front face
y_bez   = y_body - bez_d;              // bezel front face
boss_len = y_bez + D_tot/2;            // 15.81 to boss tip
y_usb   = y_rear - (D_body + bez_d)/2; // USB centred in body depth — NOT dimensioned

// rounded rectangle in XZ, extruded from y=0 toward -Y
module rr(w, h, r, len) rotate([90,0,0]) linear_extrude(len)
  offset(r) offset(-r) square([w, h], center = true);

difference() {
  union() {
    translate([0, y_rear, H/2]) rr(W, H, r_c, D_body);
    translate([0, y_body + 0.01, H/2]) rr(W - 2*bez_in, H - 2*bez_in, r_bez, bez_d + 0.01);
    for (x = lens_x)
      translate([x, y_bez + 0.01, H/2]) rotate([90,0,0])
        cyl(d = boss_base, h = boss_len + 0.01, chamfer2 = (boss_base - boss_tip)/2,
            anchor = BOT, $fn = 72);
  }
  // lens glass recesses
  for (x = lens_x)
    translate([x, -D_tot/2 - 0.01, H/2]) rotate([-90,0,0])
      cylinder(d = glass_d, h = glass_rec + 0.01, $fn = 64);
  // USB-C opening on +X end (9.5 tall, 3.5 wide)
  translate([W/2 + 0.01, y_usb, H/2])
    cuboid([usb_depth, usb_w, usb_h], rounding = usb_w/2 - 0.01, edges = "X", anchor = RIGHT, $fn = 24);
  // rear M2 holes, 4x on 116.7 x 18.1
  for (sx = [-1, 1], sz = [-1, 1])
    translate([sx*rear_dx/2, y_rear + 0.01, H/2 + sz*rear_dz/2])
      ycyl(d = m2_d, h = m2_depth + 0.01, anchor = BACK, $fn = 24);
  // bottom M2 holes, 2x 56 apart, centred in body depth (depth position NOT dimensioned)
  for (sx = [-1, 1])
    translate([sx*bot_dx/2, y_rear - D_body/2, -0.01])
      zcyl(d = m2_d, h = m2_depth + 0.01, anchor = BOT, $fn = 24);
}

include <robotics.scad>
// Origin = optical axis at boss tip plane. Front 0.3 behind tip, back seats on recess floor (y=1.0, 0.02 overlap).
translate([0, 0.3, 0]) rotate([-90,0,0]) cylinder(d = 13.9, h = 0.72, $fn = 64);

include <robotics.scad>
// USB-C receptacle shell. Origin = centre of the opening on the case end face; shell extends toward -X.
// Front face recessed 0.5 mm; back face seats on the opening floor (7 mm deep, overlap 0.02).
recess = 0.5; len = 7 - recess + 0.02;
translate([-recess, 0, 0]) difference() {
  cuboid([len, 3.2, 8.9], rounding = 1.59, edges = "X", anchor = RIGHT, $fn = 24);
  translate([0.01, 0, 0]) cuboid([len - 0.6, 2.6, 8.3], rounding = 1.29, edges = "X", anchor = RIGHT, $fn = 24);
}
